std::string license_info::getInfo()
{
    if (!this->isRegistered)
    {
        return "Unregistered";
    }
    else
    {
        std::stringstream ss;
        ss << "Registered\n";
        ss << "License ID: " << this->licenseId << "\n";
        ss << "Registered to: " << this->licenseeName << "\n";
